begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.sessions(id,user_id,created_at,updated_at,aal) values
('95000000-0000-4000-8000-000000000005','00000000-0000-4000-8000-000000000005',now(),now(),'aal1'),
('95000000-0000-4000-8000-000000000006','00000000-0000-4000-8000-000000000006',now(),now(),'aal1');
select ok(not has_table_privilege('authenticated','private.test_partner_operations','select'),'Reservations are private');
select ok((select relrowsecurity from pg_class where oid='private.test_partner_operations'::regclass),'Reservations have RLS');
select ok(not has_function_privilege('authenticated','public.rk_backend_test_partner_begin(uuid,uuid,uuid,uuid,text,jsonb,text)','execute'),'Browsers cannot reserve identities');
select ok(not has_function_privilege('anon','public.rk_backend_test_partner_finish(uuid,uuid,uuid,uuid)','execute'),'Anonymous cannot finalize partner');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select throws_ok($q$select public.rk_backend_test_partner_begin('00000000-0000-4000-8000-000000000006','95000000-0000-4000-8000-000000000006','96000000-0000-4000-8000-000000000001','96000000-0000-4000-8000-000000000002','sql-test-partner@rkmed.test','{"name":"Teste SQL","segment":"Academia","address":"Rua teste","employeeName":"Funcionário","discountBps":2000}','2468')$q$,'42501','Acesso negado','Support cannot provision partner via service guard');
reset role;
update private.settings set value='production' where key='environment';
set local role service_role;
select throws_ok($q$select public.rk_backend_test_partner_begin('00000000-0000-4000-8000-000000000005','95000000-0000-4000-8000-000000000005','96000000-0000-4000-8000-000000000001','96000000-0000-4000-8000-000000000002','sql-test-partner@rkmed.test','{"name":"Teste SQL","segment":"Academia","address":"Rua teste","employeeName":"Funcionário","discountBps":2000}','2468')$q$,'42501','Cadastro de teste indisponível neste ambiente.','Production guard denies even administrators');
reset role;
update private.settings set value='local' where key='environment';
set local role service_role;
select set_config('rkmed.test.reservation',public.rk_backend_test_partner_begin('00000000-0000-4000-8000-000000000005','95000000-0000-4000-8000-000000000005','96000000-0000-4000-8000-000000000001','96000000-0000-4000-8000-000000000002','sql-test-partner@rkmed.test','{"name":"Teste SQL","segment":"Academia","address":"Rua teste","employeeName":"Funcionário","discountBps":2000}','2468')::text,true);
select is(current_setting('rkmed.test.reservation')::jsonb->>'status','pending','Reservation precedes Auth');
select is(public.rk_backend_test_partner_begin('00000000-0000-4000-8000-000000000005','95000000-0000-4000-8000-000000000005','96000000-0000-4000-8000-000000000001','96000000-0000-4000-8000-000000000003','sql-test-partner@rkmed.test','{"name":"Teste SQL","segment":"Academia","address":"Rua teste","employeeName":"Funcionário","discountBps":2000}','2468')->>'status','busy','Concurrent operation cannot own active lease');
select throws_ok($q$select public.rk_backend_test_partner_finish('00000000-0000-4000-8000-000000000005','95000000-0000-4000-8000-000000000005','96000000-0000-4000-8000-000000000001','96000000-0000-4000-8000-000000000002')$q$,'P0001','Não foi possível vincular a conta. Retome o cadastro.','Finalization requires exact verified Auth identity');
reset role;
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data) values((current_setting('rkmed.test.reservation')::jsonb->>'authUserId')::uuid,'sql-test-partner@rkmed.test',now(),'{"rkmed_test_partner_operation":"96000000-0000-4000-8000-000000000001"}');
insert into auth.sessions(id,user_id,created_at,updated_at,aal) values('95000000-0000-4000-8000-000000000009',(current_setting('rkmed.test.reservation')::jsonb->>'authUserId')::uuid,now(),now(),'aal1');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('rkmed.test.reservation')::jsonb->>'authUserId','role','authenticated','session_id','95000000-0000-4000-8000-000000000009')::text,true);
set local role authenticated;
select throws_ok('select public.rk_context()','42501','Cadastro de parceiro em andamento. Procure a administração.','Unfinished Auth identity cannot enroll or operate');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select set_config('rkmed.test.partner',public.rk_backend_test_partner_finish('00000000-0000-4000-8000-000000000005','95000000-0000-4000-8000-000000000005','96000000-0000-4000-8000-000000000001','96000000-0000-4000-8000-000000000002')::text,true);
select is(public.rk_backend_test_partner_finish('00000000-0000-4000-8000-000000000005','95000000-0000-4000-8000-000000000005','96000000-0000-4000-8000-000000000001','96000000-0000-4000-8000-000000000002'),current_setting('rkmed.test.partner')::jsonb,'Finalization replay returns original result');
reset role;
select ok((select is_test from private.partners where id=(current_setting('rkmed.test.partner')::jsonb->>'partnerId')::uuid),'Test marker is server assigned');
select is((select count(*) from private.employees where partner_id=(current_setting('rkmed.test.partner')::jsonb->>'partnerId')::uuid),1::bigint,'Exactly one employee is created');
select is((select count(*) from private.audit where action='partner.test.created' and correlation_id='96000000-0000-4000-8000-000000000001'),1::bigint,'Exactly one attributed creation audit');
select ok((select employee_code_hash<>'2468' and employee_code_hash=extensions.crypt('2468',employee_code_hash) from private.test_partner_operations where operation_id='96000000-0000-4000-8000-000000000001'),'Journal holds only employee code hash');
set local role anon;
select ok(not exists(select 1 from jsonb_array_elements(public.rk_partners()) p where p->>'id'=current_setting('rkmed.test.partner')::jsonb->>'partnerId'),'Anonymous directory excludes test partner');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('rkmed.test.reservation')::jsonb->>'authUserId','role','authenticated','session_id','95000000-0000-4000-8000-000000000009')::text,true);
set local role authenticated;
select is(public.rk_context()->'partner'->>'name','Teste SQL','Partner context provides own hidden establishment');
select is(public.rk_context()->'partner'->>'isTest','true','Partner context identifies test environment');
select is(public.rk_start_work('2468',current_setting('rkmed.test.partner')::jsonb->>'establishmentCode')->'workSession'->>'employeeName','Funcionário','Valid establishment and employee codes start work');
reset role;
select * from finish();
rollback;
